const CONFIG = {
  owner: 'Skip-me-not',
  repository: 'horror-video-automation',
  branch: 'main',
  tts_provider: 'kokoro'
};
return [{json: {config: CONFIG, scheduled_at: new Date().toISOString()}}];

const source = $json.body ?? $json;
const demo = {
  job_id: `manual-${Date.now()}`,
  title: 'The Last Call From Room 17',
  story: 'At two in the morning, the desk phone rang. Mara answered, but heard only her own breathing. The call came from Room 17, sealed since the fire thirty years ago. The elevator opened by itself. Wet footprints crossed the empty lobby and stopped behind her. Then the phone whispered, Do not turn around.',
  description: 'An original retention-first English horror story.',
  tags: ['horror shorts', 'scary stories', 'creepy stories', 'shorts'],
  genre: 'paranormal',
  background_file: 'dark-corridor.png',
  background_queries: ['empty dark hotel corridor', 'old elevator abandoned building', 'rainy apartment windows night'],
  ambience_file: '',
  thumbnail_file: '',
  privacy_status: 'public'
};
const v = Object.keys(source).length ? source : demo;
const required = ['job_id','title','story','description','tags','background_file'];
for (const key of required) if (v[key] === undefined || v[key] === null || v[key] === '') throw new Error(`Missing field: ${key}`);
if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(v.job_id)) throw new Error('Invalid job_id');
if (typeof v.story !== 'string' || v.story.trim().length < 180 || v.story.length > 1100) throw new Error('Story length must be 180-1100 characters');
if (v.privacy_status && v.privacy_status !== 'public') throw new Error('Only public uploads are permitted');
for (const [key, exts] of Object.entries({background_file:['.mp4','.mov','.mkv','.webm','.png','.jpg','.jpeg','.webp'], ambience_file:['.mp3','.wav','.m4a','.aac','.ogg'], thumbnail_file:['.png','.jpg','.jpeg','.webp']})) {
  const name = v[key] || '';
  if (!name && key !== 'background_file') continue;
  if (name.includes('/') || name.includes('\\') || name === '..' || !exts.some(ext => name.toLowerCase().endsWith(ext))) throw new Error(`Invalid ${key}`);
}
return [{json: v}];

const CONFIG = {
  owner: 'Skip-me-not',
  repository: 'horror-video-automation',
  branch: 'main',
  tts_provider: 'kokoro',
  callback_url: 'https://REPLACE_N8N_HOST/webhook/horror-video-callback'
};
return [{json: {config: CONFIG, job: {...$json, privacy_status: 'public', callback_url: CONFIG.callback_url}}}];

const raw = JSON.stringify($json.job);
const bytes = Buffer.from(raw, 'utf8');
if (bytes.length > 50000) throw new Error('Payload exceeds the 50 KB workflow limit');
return [{json: {...$json, job_payload: bytes.toString('base64')}}];
